-- ============================================================================
-- قائمةُ 2022 تُنشَر نصيحةَ 2026، فتُبعد القارئ عن سكن مفتوح
-- ============================================================================
-- البند الرابع من أمر العمل.
--
-- ثلاث صفحات على الموقع تجيب سؤال «أي أحياء أورفا مغلقة أمام تسجيل عناوين
-- الأجانب». أطولها — 15,861 حرفاً، وأوفاها كتابةً — تجيب 170. والاثنتان
-- الأخريان تجيبان 26، وأداة /zones تجيب 26، وشريط الصفحة يطبع «أورفا (26 مغلق)».
--
-- وليست الصفحة قديمةً فحسب، بل هي نصيحةٌ عاملة:
--
--   steps[1]  «ابحث في قائمة هذا المقال … لو ظهر، الحي مغلق — لا تستأجر»
--   tips[0]   «احفظ هذا المقال على هاتفك — افتحه أمام المختار»
--   الخلاصة   «تجنّب Akçakale و Eyyübiye و Haliliye … وفكّر جدياً في Karaköprü»
--
-- أي أنّها تطلب من القارئ أن يقرّر توقيع عقد إيجاره بقائمةٍ من 31 آب 2022.
-- ومقابلتها بقائمة الولاية الصادرة في 6 حزيران 2026:
--
--     القضاء        2022   مغلق اليوم
--     Akçakale        41        7
--     Eyyübiye        31        4
--     Harran          27        1
--     Haliliye        25        9
--     Viranşehir      20        0   ← فُتح بالكامل
--     Suruç            8        4
--     Ceylanpınar      6        0   ← فُتح بالكامل
--     Birecik          3        1
--     Bozova           3        0   ← فُتح بالكامل
--     Karaköprü        3        0   ← فُتح بالكامل
--     Siverek          3        0   ← فُتح بالكامل
--     Halfeti          1        0   ← فُتح بالكامل
--     Hilvan           1        0   ← فُتح بالكامل
--     ──────────────────────────────
--     المجموع        172       26
--
-- مئةٌ وستّةٌ وأربعون حياً أُعيد فتحها. وسبعةٌ من ثلاثة عشر قضاءً صارت مفتوحة
-- من طرفها إلى طرفها. والصفحة تسمّي ثلاثة أقضية «تجنّبها» وقضاءً واحداً
-- تنصح به — والذي تنصح به، Karaköprü، مفتوحٌ بالكامل، ومثله ستّة لا تذكرها
-- خياراً أصلاً.
--
-- ── وما لا يفعله هذا الملف: حذف الصفحة ─────────────────────────────────
--
-- إكسل 2022 ما زالت هي القائمة المعمول بها في إحدى وستّين ولاية من ثلاث
-- وستّين — لم تصدر قائمة محدَّثة إلا لأورفا وقونيا — وهذه الصفحة تشرح الآلية
-- نفسها (عتبة 25% ثمّ 20%، وماذا يفعل المختار، وسلسلة وثيقة العنوان) بطولٍ
-- لا تبلغه الأخريان. فحذفها إتلافُ كتابةٍ لإصلاح إطار. الإطار هو ما يتغيّر:
-- التاريخ يدخل العنوان، وتُفتتح الصفحة بما أُعيد فتحه، وعناوين الأقضية تعرض
-- «2022 ← اليوم»، وكل تعليمةٍ كانت تطلب القرار من القائمة القديمة صارت تحيل
-- إلى الفاحص الحيّ.
--
-- ── ويُصحَّح معها الإسناد ───────────────────────────────────────────────
--
-- الصفحة الوطنية أسندت رقم الـ80% إلى منشور فيسبوك. اتحاد UCSO نقلَه؛ والذي
-- قرّره مراجعةُ وزارة الداخلية في 21 أيار 2026 وقائمةُ مديرية الهجرة في
-- 6 حزيران. فالناقل يُسمّى ناقلاً.
--
-- ── والإصلاح المرافق في الشيفرة لا في SQL ──────────────────────────────
--
-- src/app/zones/[slug]/page.tsx كانت تنشر dateModified = new Date() في بيانات
-- Dataset المهيكلة كلّما خلت صفوف الولاية من تاريخ إعادة فتح — وهي 58 ولاية من
-- 63. أي أنّ ثمانياً وخمسين صفحة كانت تخبر جوجل أنّ بياناتها عُدِّلت هذه اللحظة،
-- وتُحدِّث ذلك كل عشر دقائق، عن صفوفٍ لم تُمَسّ منذ 5 كانون الثاني 2026.
-- إشارةُ حداثةٍ ملفَّقة في حقلٍ يقرؤه الزاحف آلياً — وهو أسوأ موضع لها.
--
-- آمن لإعادة التشغيل.
-- ============================================================================

UPDATE articles SET
    title = 'أحياء شانلي أورفا المغلقة: قائمة 2022 الكاملة (172 حياً) — وما بقي منها اليوم 26',
    details = replace(replace(replace(replace(replace(replace(replace(replace('<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 22px;"><p style="margin:0 0 10px;font-size:17px;"><strong>اقرأ هذا أوّلاً: القائمة أدناه قائمة 2022، وقد أُلغي معظمها.</strong></p><p style="margin:0 0 10px;">في 6 حزيران/يونيو 2026 أصدرت مديرية الهجرة في شانلي أورفا قائمةً رسميةً جديدة، تنفيذاً لمراجعة وزارة الداخلية المعلَنة في 21 أيار/مايو 2026 بإعادة فتح الأحياء التي نزلت فيها نسبة المقيمين السوريين تحت 20%. فمن أصل <strong>172</strong> حياً في قائمة 2022 بقي <strong>26</strong> حياً مغلقاً فقط — أي أنّ <strong>146</strong> حياً أُعيد فتحها.</p><p style="margin:0 0 10px;">و<strong>7</strong> أقضية من أصل ثلاثة عشر صارت مفتوحة بالكامل: Bozova، Ceylanpınar، Halfeti، Hilvan، Karaköprü، Siverek، Viranşehir. ونصّ القائمة الرسمية نفسه يقول: «YUKARIDA İSMİ BULUNAN MAHALLELER HARİÇ İLDEKİ TÜM MAHALLELER İKAMETE AÇILMIŞTIR» — أي أنّ كل أحياء الولاية مفتوحة عدا المذكورة في تلك القائمة.</p><p style="margin:0;"><strong>فلا تقرّر من هذه الصفحة.</strong> <a href="/zones/%C5%9Eanl%C4%B1urfa" style="color:#047857;font-weight:bold;">افتح حالة أحياء أورفا الحيّة ←</a>  أو اقرأ <a href="/article/urfa-closed-neighborhoods-list-2026" style="color:#047857;font-weight:bold;">القائمة الرسمية الجديدة (26 حياً)</a>. وتبقى هذه الصفحة منشورةً لأنّ قائمة 2022 ما زالت هي المعمول بها في ستّين ولايةً أخرى لم تصدر لها قائمة محدَّثة بعد، ولأنّها تشرح الآلية نفسها: متى يُغلق الحي، وماذا يفعل المختار، وكيف تُستخرج وثيقة العنوان.</p></div>' || details, '    <li><strong>170</strong> حياً مغلقاً — الأعلى على مستوى تركيا</li>
    <li><strong>13</strong> قضاءً من أصل 13 قضاءً في الولاية (لا قضاء يخلو من حي مغلق واحد على الأقلّ)</li>
    <li><strong>Akçakale</strong> الأعلى بين الأقضية بـ41 حياً مغلقاً (قضاء حدودي مباشر مع سوريا)</li>
    <li><strong>Karaköprü</strong> الأقلّ كثافة إغلاق بين الأقضية الرئيسية بـ3 أحياء فقط — وهو غالباً الخيار الأنسب للسوريين الباحثين عن منطقة صالحة للتسجيل</li>
    <li>المصدر: <a href="https://www.goc.gov.tr" target="_blank" rel="noopener noreferrer" style="color:#0369a1;font-weight:bold;">goc.gov.tr</a> — قائمة Excel رسمية بتاريخ 31/08/2022 (آخر قائمة شاملة منشورة)</li>
  </ul>', '    <li>قائمة 2022 ضمّت <strong>172</strong> حياً مغلقاً موزّعة على ثلاثة عشر قضاءً — وكانت أورفا حينها الأعلى في تركيا</li>
    <li>وقائمة 6 حزيران/يونيو 2026 أبقت <strong>26</strong> حياً مغلقاً فقط، فأعادت فتح <strong>146</strong></li>
    <li>و<strong>7</strong> أقضية صارت مفتوحة بالكامل: Bozova، Ceylanpınar، Halfeti، Hilvan، Karaköprü، Siverek، Viranşehir</li>
    <li>المصدر: <a href="https://www.goc.gov.tr" target="_blank" rel="noopener noreferrer" style="color:#0369a1;font-weight:bold;">goc.gov.tr</a> — قائمة Excel رسمية بتاريخ 31/08/2022 (آخر قائمة شاملة منشورة)</li>
    <li>والقائمة النافذة اليوم: مديرية الهجرة في شانلي أورفا، 6/6/2026</li>
  </ul>
  <table style="width:100%;border-collapse:collapse;margin-top:14px;font-size:15px;">
    <thead><tr><th style="text-align:right;padding:6px 8px;">القضاء</th><th style="text-align:right;padding:6px 8px;">في قائمة 2022</th><th style="text-align:right;padding:6px 8px;">مغلق اليوم</th></tr></thead>
    <tbody><tr><td>Akçakale</td><td>41</td><td><strong>7</strong></td></tr><tr><td>Eyyübiye</td><td>31</td><td><strong>4</strong></td></tr><tr><td>Harran</td><td>27</td><td><strong>1</strong></td></tr><tr><td>Haliliye</td><td>25</td><td><strong>9</strong></td></tr><tr><td>Viranşehir</td><td>20</td><td><strong>لا شيء — فُتح بالكامل</strong></td></tr><tr><td>Suruç</td><td>8</td><td><strong>4</strong></td></tr><tr><td>Ceylanpınar</td><td>6</td><td><strong>لا شيء — فُتح بالكامل</strong></td></tr><tr><td>Birecik</td><td>3</td><td><strong>1</strong></td></tr><tr><td>Bozova</td><td>3</td><td><strong>لا شيء — فُتح بالكامل</strong></td></tr><tr><td>Karaköprü</td><td>3</td><td><strong>لا شيء — فُتح بالكامل</strong></td></tr><tr><td>Siverek</td><td>3</td><td><strong>لا شيء — فُتح بالكامل</strong></td></tr><tr><td>Halfeti</td><td>1</td><td><strong>لا شيء — فُتح بالكامل</strong></td></tr><tr><td>Hilvan</td><td>1</td><td><strong>لا شيء — فُتح بالكامل</strong></td></tr></tbody>
  </table>'), '<p>شانلي أورفا تحتلّ المركز الأوّل في تركيا بعدد الأحياء المغلقة أمام تسجيل إقامة الأجانب (170 حياً). إن كنت سورياً تبحث عن سكن جديد في الولاية، <strong>تجنّب Akçakale و Eyyübiye و Haliliye للأحياء المُدرجة أعلاه، وافحص قائمة Harran و Viranşehir بدقّة، وفكّر جدياً في Karaköprü</strong> حيث يبقى الإغلاق محصوراً في 3 أحياء فقط.</p>', '<p>كانت أورفا أعلى ولايات تركيا إغلاقاً بـ172 حياً في قائمة 2022. ولم تعد كذلك: المغلق اليوم 26 حياً، وأثقل الأقضية صار Haliliye بـ9 ثم Akçakale بـ7، و7 أقضية مفتوحة بالكامل.</p><p><strong>ولا تبنِ قرار سكنك على هذه الصفحة ولا على أي قائمة مطبوعة.</strong> افحص اسم الحي بالتحديد في <a href="/zones/%C5%9Eanl%C4%B1urfa" style="font-weight:bold;">صفحة أحياء أورفا الحيّة</a>، ثمّ أكّده عند المختار قبل التوقيع. فالمختار هو المرجع الإداري الأخير، وربع ساعة من السؤال توفّر عليك شهوراً.</p>'), '<h3>🔴 Akçakale (41 حي مغلق) — أعلى كثافة إغلاق</h3>', '<h3>Akçakale — كان 41 حياً مغلقاً في 2022، والمغلق اليوم 7</h3>'), '<h3>🟠 Eyyübiye (31 حي مغلق) — مركز المدينة القديم</h3>', '<h3>Eyyübiye — كان 31 حياً مغلقاً في 2022، والمغلق اليوم 4</h3>'), '<h3>🟠 Harran (26 حي مغلق) — قضاء ريفي زراعي</h3>', '<h3>Harran — كان 27 حياً مغلقاً في 2022، والمغلق اليوم 1</h3>'), '<h3>🟠 Haliliye (25 حي مغلق) — وسط المدينة الحديث</h3>', '<h3>Haliliye — كان 25 حياً مغلقاً في 2022، والمغلق اليوم 9 — وهو أكثر الأقضية إغلاقاً الآن</h3>'), '<h3>🟢 Karaköprü (3 أحياء مغلقة فقط) — الخيار الأفضل اليوم</h3>', '<h3>Karaköprü — كانت 3 أحياء مغلقة في 2022، والقضاء اليوم مفتوح بالكامل</h3>'), '<h3>🟡 Viranşehir (20 حي مغلق) — قضاء كبير شمال شرق</h3>', '<h3>Viranşehir — كان 20 حياً مغلقاً في 2022، والقضاء اليوم مفتوح بالكامل</h3>'),
    steps = ARRAY['1️⃣ احصل على اسم الحي والقضاء بالتركية — اسأل صاحب البيت أو الوسيط: "Mahalle ve ilçe adı nedir?" — مثلاً: Eyyübiye / Pınarbaşı Mahallesi. لا تكتفِ بـ"وسط المدينة" أو "قرب الجامعة".', '2️⃣ افحص الاسم في القائمة الحيّة لا في هذه الصفحة — افتح /zones/Şanlıurfa وابحث عن اسم الحي. القائمة أدناه قائمة 2022 وقد فُتح 146 حياً منها؛ ظهور الاسم فيها لا يعني أنّه مغلق اليوم.', '3️⃣ تأكّد من المختار قبل التوقيع — اذهب لمختار الحي (Muhtarlık). قُل: "Yabancıyım, ikamet kaydı yaptırmak istiyorum. Bu mahalle yabancılara açık mı?" — جوابه نهائي.', '4️⃣ اطلب وثيقة Yerleşim Yeri Belgesi — بعد قبول المختار، اطلب وثيقة العنوان رسمياً. هذه الوثيقة هي ما تأخذه لـNüfus Müdürlüğü لتسجيل عنوانك في النظام.', '5️⃣ سجّل العنوان في النفوس خلال 20 يوماً — القانون 5490 يلزمك بتسجيل العنوان في غضون 20 يوماً من الانتقال. التأخير قد يُكلّفك غرامة أو يُلغي صلاحية كيمليكك.', '6️⃣ سجّل الانتقال في إدارة الهجرة — بعد تحديث العنوان في النفوس، حدّث ملفّك في İl Göç İdaresi (إدارة الهجرة) ضمن 20 يوماً أيضاً — وإلا قد تُعتبر مفقود الأثر إدارياً.']::text[],
    tips = ARRAY['احفظ رابط /zones/Şanlıurfa على هاتفك لا قائمة 2022 — الأولى تتحدّث والثانية لا', 'لا توقّع عقد إيجار بدون شرط استرداد العربون لو رُفض التسجيل في النفوس', 'Karaköprü وViranşehir وCeylanpınar وBozova وSiverek وHalfeti وHilvan مفتوحة بالكامل اليوم — لم يعد الخيار محصوراً في قضاء واحد', 'تحقّق من الخدمات (كهرباء، ماء، إنترنت) — بعض الأحياء المفتوحة لا تتوفّر فيها كلّ الخدمات', 'لا تخلط بين «حي مغلق للأجانب» و «حي خطر أمنياً» — هما مفهومان مختلفان', 'لو رفض المختار التسجيل بحجّة الإغلاق رغم أنّ الحي يبدو مفتوحاً، اطلب رفضاً مكتوباً واتّصل بـ157']::text[],
    warning = 'القائمة المفصَّلة في هذه الصفحة صادرة في 31/08/2022، وقد فُتح 146 حياً منها بقائمة مديرية الهجرة في أورفا الصادرة في 6 حزيران/يونيو 2026 — فلم يبق مغلقاً إلا 26. فلا تستعملها لتقرّر أين تسكن؛ استعملها لتفهم الآلية، وافحص الاسم في صفحة أحياء أورفا الحيّة. والمختار هو المرجع الإداري الأخير وقراره ينفذ.',
    source = 'قائمة Excel الرسمية «Kapalı Mahalleler» على goc.gov.tr بتاريخ 31/08/2022 (القائمة الشاملة الأخيرة) + قائمة مديرية الهجرة في شانلي أورفا الصادرة في 6/6/2026 + مراجعة وزارة الداخلية المعلَنة في 21/5/2026',
    last_update = CURRENT_DATE
WHERE slug = 'urfa-closed-neighborhoods-residence-2026';

UPDATE articles SET
    source = 'مراجعة وزارة الداخلية التركية المعلَنة في 21/5/2026 + القوائم الولائية الصادرة عن مديريات الهجرة (أورفا 6/6/2026، قونيا) — نقلها اتحاد منظمات المجتمع المدني للتنمية (UCSO) في 6/6/2026',
    last_update = CURRENT_DATE
WHERE slug = 'closed-neighborhoods-80-percent-reduction-2026';

UPDATE articles SET
    source = 'مديرية الهجرة في شانلي أورفا — القائمة الرسمية الصادرة في 6/6/2026، تنفيذاً لمراجعة وزارة الداخلية المعلَنة في 21/5/2026؛ نقلها اتحاد منظمات المجتمع المدني للتنمية (UCSO)',
    last_update = CURRENT_DATE
WHERE slug = 'urfa-closed-neighborhoods-list-2026';

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — كل صفّ true
SELECT 'urfa-2022 reframed' AS البند,
       (title LIKE '%%قائمة 2022%%'
        AND details LIKE '%%اقرأ هذا أوّلاً%%'
        AND details NOT LIKE '%%تجنّب Akçakale%%'
        AND details NOT LIKE '%%الخيار الأفضل اليوم%%') AS سليم
FROM articles WHERE slug = 'urfa-closed-neighborhoods-residence-2026'
UNION ALL
SELECT 'urfa-2022 steps/tips',
       (array_to_string(steps, ' ') NOT LIKE '%%ابحث في قائمة هذا المقال%%'
        AND array_to_string(tips, ' ') NOT LIKE '%%احفظ هذا المقال على هاتفك%%')
FROM articles WHERE slug = 'urfa-closed-neighborhoods-residence-2026'
UNION ALL
SELECT 'national page off facebook', (source NOT LIKE '%%facebook%%')
FROM articles WHERE slug = 'closed-neighborhoods-80-percent-reduction-2026'
UNION ALL
SELECT 'no page claims 170 closed now', (count(*) = 0)::boolean FROM articles
  WHERE status = 'approved' AND title LIKE '%%170 حي)%%';
